const normalize = (value: string) => value.replace(/\s+/g, " ").trim().toLowerCase();
const preserve = (source: string, translated: string) => `${source.match(/^\s*/)?.[0] ?? ""}${translated.trim()}${source.match(/\s*$/)?.[0] ?? ""}`;
const phraseEntries = Object.entries(EXACT)
  .filter(([key]) => key.includes(" "))
  .sort((a, b) => b[0].length - a[0].length)
  .map(([en, bn]) => [new RegExp(en.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\s+/g, "\\s+"), "gi"), bn] as const);

function translateBanglaPattern(source: string): string | null {
  const trimmed = source.trim();
  const patterns: Array<[RegExp, (rest: string) => string]> = [
    [/^upload\s+(.+)$/i, (rest) => `${translateText(rest, "bn")} আপলোড করুন`],
    [/^download\s+(.+)$/i, (rest) => `${translateText(rest, "bn")} ডাউনলোড করুন`],
    [/^select\s+(.+)$/i, (rest) => `${translateText(rest, "bn")} নির্বাচন করুন`],
    [/^choose\s+(.+)$/i, (rest) => `${translateText(rest, "bn")} নির্বাচন করুন`],
    [/^create\s+(.+)$/i, (rest) => `${translateText(rest, "bn")} তৈরি করুন`],
    [/^add\s+(.+)$/i, (rest) => `${translateText(rest, "bn")} যোগ করুন`],
    [/^remove\s+(.+)$/i, (rest) => `${translateText(rest, "bn")} সরান`],
    [/^delete\s+(.+)$/i, (rest) => `${translateText(rest, "bn")} মুছে দিন`],
    [/^change\s+(.+)$/i, (rest) => `${translateText(rest, "bn")} পরিবর্তন করুন`],
    [/^edit\s+(.+)$/i, (rest) => `${translateText(rest, "bn")} এডিট করুন`],
    [/^open\s+(.+)$/i, (rest) => `${translateText(rest, "bn")} খুলুন`],
    [/^view\s+(.+)$/i, (rest) => `${translateText(rest, "bn")} দেখুন`],
    [/^search\s+(.+)$/i, (rest) => `${translateText(rest, "bn")} খুঁজুন`],
  ];
  for (const [pattern, make] of patterns) {
    const match = trimmed.match(pattern);
    if (match?.[1]) return make(match[1]);
  }
  const noMatch = trimmed.match(/^no\s+(.+?)\s+found\.?$/i);
  if (noMatch?.[1]) return `কোনো ${translateText(noMatch[1], "bn")} পাওয়া যায়নি।`;
  return null;
}

export function translateText(value: unknown, locale: Locale = getCurrentLocale()): string {
  const source = String(value ?? "");
  if (locale === "en" || !/[A-Za-z]/.test(source)) return source;
  const exact = EXACT[normalize(source)];
  if (exact) return preserve(source, exact);
  const patterned = translateBanglaPattern(source);
  if (patterned) return preserve(source, patterned);
  let out = source;
  for (const [pattern, replacement] of phraseEntries) out = out.replace(pattern, replacement);
  out = out.replace(/[A-Za-z][A-Za-z'-]*/g, (token) => WORDS[token.toLowerCase()] ?? token);
  return out;
}

export function getCurrentLocale(): Locale {
  if (typeof document === "undefined") return DEFAULT_LOCALE;
  return document.documentElement.getAttribute("data-locale") === "bn" ? "bn" : "en";
}

export function readStoredLocale(): Locale {
  if (typeof document === "undefined") return DEFAULT_LOCALE;
  try {
    const local = window.localStorage.getItem(LOCALE_STORAGE);
    if (local === "bn" || local === "en") return local;
  } catch {}
  const match = document.cookie.match(new RegExp(`(?:^|; )${LOCALE_COOKIE}=([^;]+)`));
  return match?.[1] === "bn" ? "bn" : DEFAULT_LOCALE;
}


export function persistLocale(locale: Locale) {
  if (typeof document === "undefined") return;
  try { window.localStorage.setItem(LOCALE_STORAGE, locale); } catch {}
  document.cookie = `${LOCALE_COOKIE}=${locale}; path=/; max-age=31536000; samesite=lax`;
  document.documentElement.lang = locale;
  document.documentElement.setAttribute("data-locale", locale);
}
